(() => {
  const r = document.scrollingElement || document.documentElement;
  const pageNoScroll = r.scrollHeight === r.clientHeight;
  const wrap = document.querySelector('.stat-table-wrap');
  const th = document.querySelector('thead th.sticky-head') || document.querySelector('thead .sticky-head');
  const tds = document.querySelectorAll('.sticky-cell');
  if (wrap) wrap.scrollTop = 0;
  const t0 = th ? th.getBoundingClientRect().top : null;
  if (wrap) wrap.scrollTop = 280;
  const t1 = th ? th.getBoundingClientRect().top : null;
  const cs = th ? getComputedStyle(th) : null;
  return JSON.stringify({
    pageNoScroll,
    stickyHead: !!(cs && cs.position === 'sticky'),
    stickyTop: cs ? cs.top : null,
    topStable: t0 !== null && t1 !== null && Math.abs(t0 - t1) < 2,
    t0,
    t1,
    wrapOverflow: wrap ? getComputedStyle(wrap).overflow : null,
    leftStickyCount: tds.length
  });
})();

(function(){
  var el = document.querySelector('.stat-table-wrap');
  if (!el) return 'no-wrap';
  window.__stickyDemo = window.__stickyDemo || 0;
  if (window.__stickyDemo === 0) { el.scrollTop = 0; el.scrollLeft = 0; window.__stickyDemo = 1; return 'top:' + el.scrollTop; }
  el.scrollTop = 520;
  return 'scrolled:' + el.scrollTop + ',scrollH:' + el.scrollHeight + ',clientH:' + el.clientHeight;
})();

